echo "== 1. reply entries vs open threads =="
node -e "
const fs=require('fs');
const raw=JSON.parse(fs.readFileSync('input/pr-1378/pr_discussions_raw.json','utf8'));
const out=JSON.parse(fs.readFileSync('outputs/review_replies.json','utf8'));
const open=raw.threads.filter(t=>!t.resolved);
console.log('open threads:',open.length,'| reply entries:',out.replies.length);
let ok=true;
for(const t of open){
  const e=out.replies.find(r=>r.threadId===t.threadId);
  if(!e){ok=false;console.log('MISSING reply for',t.threadId);continue;}
  if(e.inReplyToId!==t.rootCommentId){ok=false;console.log('BAD inReplyToId for',t.threadId,e.inReplyToId,'!=',t.rootCommentId);}
  if(!fs.existsSync(e.reply)){ok=false;console.log('MISSING file',e.reply);}
  if(e.reply.indexOf('outputs/review_replies/')!==0){ok=false;console.log('reply field is not a path:',e.reply);}
  if(!e.threadId.startsWith('PRRT_kwDORYAuYs6')){ok=false;console.log('threadId malformed:',e.threadId);}
}
console.log(ok?'ALL THREADS COVERED, ids verbatim, files exist':'FAILURES ABOVE');
"
